package ec.edu.unl.sec.evidence.domain;import java.util.*;public record VersionIndicator(UUID versionId,UUID indicatorId,String code,String title,int position){public VersionIndicator{Objects.requireNonNull(versionId);Objects.requireNonNull(indicatorId);code=text(code,100);title=text(title,300);if(position<1)throw new IllegalArgumentException("position must be positive");}private static String text(String v,int max){if(v==null||v.isBlank()||v.strip().length()>max)throw new IllegalArgumentException("invalid indicator snapshot");return v.strip();}}
